head.b:skin:
/* 
THEME: Storyteller Framework (Midnight Purple & Dream Edition)
SYSTEM: Creative Narrative Engine
*/
:root {
    --royal-purple: #2d1b4e;
    --magic-pink: #f472b6;
    --deep-space: #1a103d;
    --starlight: #faf5ff;
    --text-main: #334155;
}
body {
    background-color: var(--deep-space);
    color: var(--text-main);
    font-family: 'Quicksand', 'Segoe UI', sans-serif;
    margin: 0; padding: 0;
}
.header-wrap {
    background: linear-gradient(135deg, var(--royal-purple), #0f172a);
    color: var(--magic-pink);
    padding: 50px 20px;
    text-align: center;
    border-bottom: 3px dashed var(--magic-pink);
}
.main-container {
    max-width: 800px;
    margin: -30px auto 50px;
    padding: 20px;
}
.story-card {
    background: var(--starlight);
    border-radius: 20px;
    box-shadow: 0 15px 40px rgba(0,0,0,0.4);
    padding: 30px;
    margin-bottom: 25px;
    border: 2px solid var(--magic-pink);
}
.input-group { margin-bottom: 20px; }
.input-group label {
    display: block;
    font-weight: bold;
    margin-bottom: 8px;
    color: var(--royal-purple);
    font-size: 14px;
    text-transform: uppercase;
    letter-spacing: 1px;
}
.input-group input, .input-group textarea {
    width: 100%;
    padding: 15px;
    border: 2px solid #e2e8f0;
    border-radius: 12px;
    font-family: inherit;
    box-sizing: border-box;
    background: #fff;
    transition: 0.3s;
}
.input-group input:focus, .input-group textarea:focus {
    border-color: var(--magic-pink);
    outline: none;
    box-shadow: 0 0 10px rgba(244, 114, 182, 0.2);
}
.input-group textarea { height: 120px; }

.lang-options { display: flex; gap: 20px; margin-top: 5px; }
.lang-item { display: flex; align-items: center; cursor: pointer; font-weight: 600; color: var(--royal-purple); }
.lang-item input { width: auto; margin-right: 8px; }

h2 { color: var(--royal-purple); text-align: center; margin-top: 0; font-size: 24px; }

.copy-btn {
    background: linear-gradient(to right, var(--magic-pink), #ec4899);
    color: white;
    border: none;
    padding: 18px 20px;
    cursor: pointer;
    font-weight: bold;
    border-radius: 12px;
    width: 100%;
    transition: 0.3s;
    font-size: 16px;
    text-transform: uppercase;
    box-shadow: 0 4px 15px rgba(236, 72, 153, 0.4);
}
.copy-btn:hover { transform: scale(1.02); filter: brightness(1.1); }
footer { text-align: center; color: #94a3b8; padding: 20px; font-size: 13px; }

body.script:
function copyPrompt() {
    var title = document.getElementById("inputTitle").value || "Kisah Tak Terduga";
    var notes = document.getElementById("inputNotes").value || "Berikan kejutan ajaib di dalamnya.";

    var selectedLang = document.querySelector('input[name="lang"]:checked').value;
    var template = (selectedLang === 'id') ? 
                   document.getElementById("templateID").innerText : 
                   document.getElementById("templateEN").innerText;

    var finalPrompt = template.replace("[USER_TITLE]", title).replace("[USER_NOTES]", notes);

    var tempElem = document.createElement("textarea");
    tempElem.value = finalPrompt;
    document.body.appendChild(tempElem);
    tempElem.select();
    document.execCommand("copy");
    document.body.removeChild(tempElem);

    alert("✨ Magic Prompt (" + (selectedLang === 'id' ? 'Bahasa Indonesia' : 'English') + ") berhasil disalin! Silakan tempel di AI.");
}
